const MAX_SUBSTEP = 10; // px: keeps every per-step displacement shorter than the paddle band (12) and the ball diameter (14)

export function step(state, dt) {
  const { ball, paddle } = state;
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(distance / MAX_SUBSTEP));
  const subDt = dt / substeps;

  for (let i = 0; i < substeps; i++) {
    const prev = { x: ball.x, y: ball.y };
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) { ball.x = ball.r; ball.vx = Math.abs(ball.vx); }
    else if (ball.x + ball.r > WIDTH) { ball.x = WIDTH - ball.r; ball.vx = -Math.abs(ball.vx); }

    // Ceiling
    if (ball.y - ball.r < 0) { ball.y = ball.r; ball.vy = Math.abs(ball.vy); }

    // Paddle ... (as above)

    // Bricks
    resolveBrickCollisions(state, prev);
  }

  if (ball.y - ball.r > HEIGHT) return true;
  return false;
}
```

