export function resolveBrickCollisions(state, prev) {
  const { ball, bricks } = state;
  const overlapped = [];
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    overlapped.push(brick);
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
  if (overlapped.length === 0) return false;

  // One bounce per axis, whatever the number of overlapped bricks: a grid seam
  // can overlap two bricks in the same pass, and two `vy = -vy` would cancel
  // and let the ball through (ghost collision).
  let flipVy = false;
  let top = Infinity;
  let bottom = -Infinity;
  for (const brick of overlapped) {
    // Face crossed during this move: flip vy and push out vertically.
    const crossedTop = ball.vy > 0 && prev.y + ball.r <= brick.y;
    const crossedBottom = ball.vy < 0 && prev.y - ball.r >= brick.y + brick.h;
    if (crossedTop) {
      flipVy = true;
      top = Math.min(top, brick.y);
    } else if (crossedBottom) {
      flipVy = true;
      bottom = Math.max(bottom, brick.y + brick.h);
    }
  }
  if (flipVy) {
    ball.vy = -ball.vy;
    ball.y = ball.vy < 0 ? top - ball.r : bottom + ball.r;
  } else {
    // Residual overlap: no face was crossed during this move (the ball was
    // already inside the brick). Push it out through the face it is moving
    // toward — its velocity already points the way out, so it must NOT be
    // flipped, or it would re-enter and vibrate (sticky defect).
    const brick = overlapped[0];
    if (Math.abs(ball.vy) >= Math.abs(ball.vx)) {
      ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    } else {
      ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    }
  }
  return true;
}

