The substep loop in step(): split the move into substeps of ≤ MAX_SUBSTEP px (10), resolving walls/paddle/bricks after each substep. Each substep gets its own prev.

```js
const MAX_SUBSTEP = 10; // px — shorter than the paddle band (12) and the ball diameter (14)

export function step(state, dt) {
  const { ball, paddle } = state;
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(distance / MAX_SUBSTEP));
  const subDt = dt / substeps;

  for (let i = 0; i < substeps; i++) {
    const prev = { x: ball.x, y: ball.y };

    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle: the ball's box vs the paddle's box (corner hits included). The
    // band test catches every crossing because a substep (≤ 10 px) is shorter
    // than the band (12 px).
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x + ball.r > paddle.x &&
      ball.x - ball.r < paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      ball.vy = -Math.abs(ball.vy);
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: destroy, score and bounce in one pure pass.
    resolveBrickCollisions(state, prev);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

