  st.ball.vx = speed * 0.5;
  while (frames < 30000) {
    frames++;
    st.paddle.x = Math.max(0, Math.min(WIDTH - st.paddle.w, st.ball.x - st.paddle.w / 2));
    const before = { x: st.ball.x, y: st.ball.y, vx: st.ball.vx, vy: st.ball.vy };
    const lostNow = step(st, 1 / 60);
    if (lostNow) { lost++; st.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed }; }
