  let frames = 0, paddleHits = 0, lost = 0;
  // diagonal launch with norm == level speed (as after the first paddle bounce)
  st.ball.vx = speed * 0.5;
  st.ball.vy = -Math.sqrt(speed * speed - st.ball.vx * st.ball.vx);
  while (frames < 120000) {
    frames++;
    st.paddle.x = Math.max(0, Math.min(WIDTH - st.paddle.w, st.ball.x - st.paddle.w / 2));
    const before = { x: st.ball.x, y: st.ball.y };
    const vyBefore = st.ball.vy;
    const lostNow = step(st, 1 / 60);
    if (lostNow) { lost++; st.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -Math.sqrt(speed * speed - st.ball.vx * st.ball.vx) }; }
    if (vyBefore < 0 && st.ball.vy > 0 && Math.abs(st.ball.x - st.paddle.x) < st.paddle.w / 2 + BALL_R) paddleHits++;
    const norm = Math.hypot(st.ball.vx, st.ball.vy);
    if (Math.abs(norm - speed) > 1e-6) { report(`L${level} frame ${frames}: speed drifted ${norm.toFixed(2)} != ${speed}`); break; }
    for (const b of st.bricks) {
      if (b.alive && collides(st.ball, b)) { report(`L${level} frame ${frames}: ball overlapping live brick`); ok = false; break; }
    }
    if (!ok) break;
    const d = Math.hypot(st.ball.x - before.x, st.ball.y - before.y);
    if (d > 10.01) { report(`L${level} frame ${frames}: jumped ${d.toFixed(1)} px in one step`); break; }
    if (st.ball.y - BALL_R > HEIGHT) { report(`L${level}: ball exited without lost flag`); break; }
    if (st.ball.x < -20 || st.ball.x > WIDTH + 20 || st.ball.y < -20) { report(`L${level}: out of bounds`); break; }
    if (st.bricks.every((b) => !b.alive)) { st.level++; st.bricks = makeBricks(st.level); st.ball = createState(st.level).ball; }
  }
  console.log(`level ${level}: ${frames} frames, ~${paddleHits} paddle hits, ${lost} lost — ${ok ? 'OK' : 'PROBLEM'}`);
  if (!ok) break;
}
