// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) -----------------------

// Resolves the ball against every live brick it overlaps: the brick is
// destroyed and scored, the ball bounces off the face it crossed during the
// last move (see `prev`), and is pushed back out of the brick.
// `prev` is the ball position BEFORE the move that produced the overlap: a
// face counts as crossed only if the ball was on its outside before the move.
// This is what tells a top-face hit from a side hit (and a corner from a
// face), and what keeps a diagonal side hit from flipping the wrong axis.
// Returns true if at least one brick was touched.
export function resolveBrickCollisions(state, prev) {
  const { ball, bricks } = state;
  const overlapped = [];
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    overlapped.push(brick);
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
  if (overlapped.length === 0) return false;

  // One bounce per axis, whatever the number of overlapped bricks: a grid seam
  // can overlap two bricks in the same pass, and two `vy = -vy` would cancel
  // and let the ball through (ghost collision).
  let flipVx = false;
  let flipVy = false;
  let left = Infinity;
  let right = -Infinity;
  let top = Infinity;
  let bottom = -Infinity;
  for (const brick of overlapped) {
    // The face crossed during this move decides the bounce axis: a side hit
    // flips vx, a top/bottom hit flips vy, a corner (both crossed in the same
    // move) flips both. `prev` is what tells a face from a corner.
    const crossedTop = ball.vy > 0 && prev.y + ball.r <= brick.y;
    const crossedBottom = ball.vy < 0 && prev.y - ball.r >= brick.y + brick.h;
    const crossedLeft = ball.vx > 0 && prev.x + ball.r <= brick.x;
    const crossedRight = ball.vx < 0 && prev.x - ball.r >= brick.x + brick.w;
    if (crossedTop) {
      flipVy = true;
      top = Math.min(top, brick.y);
    }
    if (crossedBottom) {
      flipVy = true;
      bottom = Math.max(bottom, brick.y + brick.h);
    }
    if (crossedLeft) {
      flipVx = true;
      left = Math.min(left, brick.x);
    }
    if (crossedRight) {
      flipVx = true;
      right = Math.max(right, brick.x + brick.w);
    }
  }
  if (flipVx) {
    ball.vx = -ball.vx;
    ball.x = ball.vx < 0 ? left - ball.r : right + ball.r;
  }
  if (flipVy) {
    ball.vy = -ball.vy;
    ball.y = ball.vy < 0 ? top - ball.r : bottom + ball.r;
  }
  if (!flipVx && !flipVy) {
    // Residual overlap: no face was crossed during this move (the ball was
    // already inside the brick). Push it out through the face it is moving
    // toward — its velocity already points the way out, so it must NOT be
    // flipped, or it would re-enter and vibrate (sticky defect).
    const brick = overlapped[0];
    if (Math.abs(ball.vy) >= Math.abs(ball.vx)) {
      ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    } else {
      ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    }
  }
  return true;
}

// Maximum distance the ball may travel in a single substep. Kept shorter than
// the paddle band (PADDLE_H = 12) and the ball diameter (14): no obstacle can
// be skipped in one substep, whatever the speed (defect D5, tunneling).
const MAX_SUBSTEP = 10;

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Split the move into substeps short enough that a fast ball cannot skip an
  // obstacle (a 12 px paddle band, a brick face) between two checks.
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(distance / MAX_SUBSTEP));
  const subDt = dt / substeps;

  for (let i = 0; i < substeps; i++) {
    const prev = { x: ball.x, y: ball.y };

    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle. The x-test uses the ball's BOX, not its center, so a ball
    // overlapping a paddle corner still bounces. The band test catches every
    // crossing because a substep (≤ 10 px) is shorter than the band (12 px).
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x + ball.r > paddle.x &&
      ball.x - ball.r < paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      // The rebound angle depends on where the paddle was hit; the speed stays
      // exactly at the level speed (a rewritten vx without renormalizing would
      // grow without bound over repeated edge hits — defect D6).
      const speed = ballSpeed(state.level);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = speed * 0.6 * hit;
      ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: destroy, score and bounce in one pure pass.
    resolveBrickCollisions(state, prev);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

