// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  BRICK_ROWS,
  BRICK_COLS,
  BALL_R,
  PADDLE_Y,
  BRICK_TOP,
  WIDTH,
} from './neon.js';

// Small local helper: the live brick at a given row and column x.
function brickAt(state, row, x) {
  return state.bricks.find((b) => b.row === row && b.x === x);
}

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick collision (defect D1: the ball never bounced off bricks) --------

test('D1: ball hitting the bottom face of a brick bounces back down', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 84); // row 4 (bottom): y 160..180, x 84..156
  state.ball = { x: 100, y: 188, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  assert.equal(brick.alive, false, 'the brick must be destroyed');
  assert.ok(state.ball.vy > 0, 'vy flips: the ball bounces down off the brick');
  assert.equal(collides(state.ball, brick), false, 'the ball leaves the brick');
});

test('D2: an overlapping ball is separated from the brick, no re-flip', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 4); // x 4..76, y 160..180
  state.ball = { x: 40, y: 178, r: BALL_R, vx: 0, vy: -ballSpeed(1) }; // deep inside, exiting upward
  step(state, 1 / 60);
  assert.equal(collides(state.ball, brick), false, 'the ball is pushed out of the brick');
  assert.ok(state.ball.vy < 0, 'exiting velocity is not flipped');
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'second step: no re-flip, the ball does not vibrate');
});

test('D3: ball straddling the seam between two bricks bounces exactly once', () => {
  const state = createState(1);
  const a = brickAt(state, 0, 4);  // x 4..76,  y 48..68
  const b = brickAt(state, 0, 84); // x 84..156
  state.ball = { x: 80, y: BRICK_TOP - BALL_R, r: BALL_R, vx: 0, vy: ballSpeed(1) }; // on the seam, above row 0
  step(state, 1 / 60);
  assert.equal(a.alive, false, 'left brick destroyed');
  assert.equal(b.alive, false, 'right brick destroyed');
  assert.ok(state.ball.vy < 0, 'exactly one vy flip: the ball bounces back up');
  assert.equal(collides(state.ball, a), false);
  assert.equal(collides(state.ball, b), false);
});

test('D4: side hit flips vx and leaves vy untouched', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 4); // x 4..76, y 160..180
  state.ball = { x: -4, y: 170, r: BALL_R, vx: ballSpeed(1), vy: 100 }; // entering from the left
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx flips on a side hit');
  assert.equal(state.ball.vy, 100, 'vy is untouched on a side hit');
  assert.equal(collides(state.ball, brick), false);
});

test('D4: corner hit flips both axes', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 4); // x 4..76, y 48..68
  state.ball = { x: -4, y: BRICK_TOP - BALL_R, r: BALL_R, vx: ballSpeed(1), vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'corner hit flips both components');
  assert.equal(collides(state.ball, brick), false);
});

// --- Paddle (defect D5: the 12 px band can be skipped in one step, and the
// x-test uses the ball center, letting the ball clip the paddle corners) -----

test('D5: paddle bounce happens exactly on the top face — no tunneling, no mid-air bounce', () => {
  // level 5: 620 px/s, dt capped at 0.05 -> 31 px/step vs a 12 px band.
  const fast = createState(5);
  fast.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(5) }; // bottom edge 447
  const lost = step(fast, 0.05);
  assert.equal(lost, false, 'the ball is not lost');
  assert.ok(fast.ball.vy < 0, 'the fast descent bounces off the paddle');

  // level 1, ball 5 px above the paddle: still descending, must not bounce in the air.
  const slow = createState(1);
  slow.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 5, r: BALL_R, vx: 0, vy: ballSpeed(1) }; // bottom edge 443
  step(slow, 1 / 60);
  assert.ok(slow.ball.vy > 0, 'ball above the paddle keeps descending');
});

test('D5: ball overlapping the paddle corner bounces even with its center outside the span', () => {
  const state = createState(1);
  state.ball = { x: state.paddle.x - 5, y: PADDLE_Y - BALL_R - 3, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'the ball bounces off the paddle corner');
});

// --- Paddle speed (defect D6: the paddle bounce rewrote vx without
// renormalizing, so the ball speed grew without bound) -----------------------

test('D6: a paddle bounce keeps the ball speed at the level speed', () => {
  const state = createState(1);
  state.ball = { x: state.paddle.x + state.paddle.w - 1, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'the ball bounces up off the paddle');
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(
    Math.abs(norm - ballSpeed(1)) < 1e-6,
    `speed must stay at the level speed (${ballSpeed(1)}), got ${norm.toFixed(1)}`
  );
});

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

